def apply_discount(cart):
    rate = resolve_rate(cart)
    return cart.total * (1 - rate)

def resolve_rate(cart):
    return lookup_tier_rate(cart.customer_tier, cart.region)

def lookup_tier_rate(tier, region):
    base = TIER_TABLE[tier]
    return apply_region_modifier(base, region)

def apply_region_modifier(base, region):
    return base * REGION_MODIFIERS.get(region, 1.0)
